official.do_attack:
void do_attack(entity *e)
{
    int them;
    int i, t;
    int force = 0;
    e_blocktype blocktype;
    entity *temp            = NULL;
    entity *flash           = NULL;    // Used so new flashes can be used
    entity *def             = NULL;
    entity *topowner        = NULL;
    entity *otherowner      = NULL;
    entity *target          = NULL;
    s_anim      *current_anim;
    s_collision_attack *attack = NULL;
    int didhit              = 0;
    int didblock            = 0;    // So a different sound effect can be played when an attack is blocked
    int current_attack_id;
    int current_follow_id   = 0;
    //int hit_detected        = 0;    // Has a hit been detected?


#define followed (current_anim!=e->animation)
    static unsigned int new_attack_id = 1;
    int fdefense_blockthreshold; //max damage that can be blocked for attack type.

    // Can't get hit after this
    if(level_completed)
    {
        return;
    }

    topowner = e; // trace the top owner, for projectile combo checking :)
    while(topowner->owner)
    {
        topowner = topowner->owner;
    }

    if(e->projectile > 0)
    {
        them = e->modeldata.projectilehit;
    }
    else
    {
        them = e->modeldata.candamage;
    }

    // Every attack gets a unique ID to make sure no one
    // gets hit more than once by the same attack
    current_attack_id = e->attack_id_outgoing;

    if(!current_attack_id)
    {
        ++new_attack_id;
        if(new_attack_id == 0)
        {
            new_attack_id = 1;
        }
        e->attack_id_outgoing = current_attack_id = new_attack_id;
    }


    current_anim = e->animation;

    for(i = 0; i < ent_max && !followed; i++)
    {
        target = ent_list[i];

        if(!target->exists)
        {
            continue;
        }

        // Check collision. If a collision
        // is found, lasthit the impacting
        // collision pointers are also
        // populated into lasthit, which
        // we will use below.
        if(!checkhit(e, target))
        {
            continue;
        }

        attack = lasthit.attack;
        fdefense_blockthreshold = (int)self->defense[attack->attack_type].blockthreshold; //max damage that can be blocked for attack type.
        force = attack->attack_force;

        // Verify target is alive.
        if(target->dead)
        {
            continue;
        }

        // Verify target is invincible,
        // or attack type is an item.
        // This is too allow item collection
        // even while invincible.
        if(target->invincible)
        {
            if(attack->attack_type != ATK_ITEM)
            {
                continue;
            }
        }

        // If attack is set to only hit
        // one entity at a _time (attackone),
        // we verify last hit (lasthit) is
        // set. If last hit is set and
        // differs from current target,
        // then we are trying to hit
        // another entity and should exit.
        if(current_anim->attackone)
        {
            if(e->lasthit)
            {
                if(target != e->lasthit)
                {
                    continue;
                }
            }
        }

        // Verify target has a match to
        // projectile hit or can damage.
        if(!(target->modeldata.type & them))
        {
            continue;
        }

        // Pain _time must have expired.
        // This is to allow reasonable delay
        // between hits so engine will not
        // run hit on every update.
        if(target->pain_time >= _time)
        {
            continue;
        }

        // Target takedamage flag
        // must be set.
        if(!target->takedamage)
        {
            continue;
        }

        // Attack IDs must be different.
        if(target->attack_id_incoming == current_attack_id && !attack->ignore_attack_id)
        {
            continue;
        }

        // Target laying down? Exit if
        // attack only hits standing targets.
        if(target->takeaction == common_lie)
        {
            if(attack->otg == OTG_NONE)
            {
                continue;
            }
        }

        // Target NOT laying down? Exit if
        // attack only hits grounded targets.
        if(target->takeaction != common_lie)
        {
            if(attack->otg == OTG_GROUND_ONLY)
            {
                continue;
            }
        }

        // If falling, then check the juggle cost.
        if(target->falling == 1)
        {
            if(attack->jugglecost > target->modeldata.jugglepoints.current)
            {
                continue;
            }
        }

        temp = self;
        self = target;

        // Execute the doattack scripts so author can set take action
        // before the hit code below does.
        execute_ondoattack_script(self, e, attack, EXCHANGE_RECIPIANT, current_attack_id);
        execute_ondoattack_script(e, self, attack, EXCHANGE_CONFERRER, current_attack_id);

        // 2010-12-31
        // Damon V. Caskey

        // If lasthit.confirm is not true, it must have been turned off by the author; almost
        // certainly with the ondoattack event scripts above. Skip the engine's
        // default hit handling below. Useful for scripting parry systems, alternate blocking,
        // or other custom collision events.
        if(lasthit.confirm)
        {
            didhit = 1;
        }
        else
        {
            // By White Dragon
            // This line: self = temp; is the fix for
            // !lasthit.confirm bug. Without it when
            // active lasthitc 0 the damagetaker has
            // weird speedy effect.
            self = temp;
            continue;
        }

        otherowner = self; // trace top owner for opponent
        while(otherowner->owner)
        {
            otherowner = otherowner->owner;
        }

        //if #01, if they are fired by the same owner, or the owner itself
        if(topowner == otherowner)
        {
            didhit = 0;
        }

        //if #02 , ground missle checking, and bullets wont hit each other
        if( (e->owner && self->owner) ||
                (e->modeldata.ground && inair(e))  )
        {
            didhit = 0;
        }//end of if #02

        //if #05,   blocking code section
        if(didhit)
        {
            if(attack->attack_type == ATK_ITEM)
            {
                do_item_script(self, e);

                didfind_item(e);
                return;
            }
            //if #051
            if(self->toexplode == 1)
            {
                self->toexplode = 2;    // Used so the bomb type entity explodes when hit
            }
            //if #052
            if(e->toexplode == 1)
            {
                e->toexplode = 2;    // Used so the bomb type entity explodes when hitting
            }

            if(inair(self))
            {
                self->modeldata.jugglepoints.current = self->modeldata.jugglepoints.current - attack->jugglecost;    //reduce available juggle points.
            }

            //if #053
            if( !self->modeldata.nopassiveblock && // cant block by itself
                    validanim(self, ANI_BLOCK) && // of course, move it here to avoid some useless checking
                    ((self->modeldata.guardpoints.max == 0) || (self->modeldata.guardpoints.max > 0 && self->modeldata.guardpoints.current > 0)) &&
                    !(self->link ||
                      inair(self) ||
                      self->frozen ||
                      (self->direction == e->direction && self->modeldata.blockback < 1) ||                       // Can't block an attack that is from behind unless blockback flag is enabled
                      (!self->idling && self->attacking != ATTACKING_INACTIVE)) &&                                                 // Can't block if busy, attack <0 means the character is preparing to attack, he can block during this time
                    attack->no_block <= self->defense[attack->attack_type].blockpower &&       // If unblockable, will automatically hit
                    (rand32()&self->modeldata.blockodds) == 1 && // Randomly blocks depending on blockodds (1 : blockodds ratio)
                    (!self->modeldata.thold || (self->modeldata.thold > 0 && self->modeldata.thold > force)) &&
                    (!fdefense_blockthreshold ||                                                                //Specific attack type threshold.
                     (fdefense_blockthreshold > force)))
            {
                //execute the didhit script
                execute_didhit_script(e, self, attack, 1);
                self->takeaction = common_block;
                set_blocking(self);
                self->velocity.x = self->velocity.z = 0;
                ent_set_anim(self, ANI_BLOCK, 0);

                execute_didblock_script(self, e, attack);

                if(self->modeldata.guardpoints.max > 0)
                {
                    self->modeldata.guardpoints.current = self->modeldata.guardpoints.current - attack->guardcost;
                }
                ++current_anim->animhits;
                didblock = 1;    // Used for when playing the block.wav sound
                // Spawn a flash
                //if #0531
                if(!attack->no_flash)
                {
                    if(!self->modeldata.noatflash)
                    {
                        if(attack->blockflash >= 0)
                        {
                            flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, attack->blockflash, NULL);    // custom bflash
                        }
                        else
                        {
                            flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, ent_list[i]->modeldata.bflash, NULL);    // New block flash that can be smaller
                        }
                    }
                    else
                    {
                        flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, self->modeldata.bflash, NULL);
                    }
                    //ent_default_init(flash); // initiliaze this because there're no default values now

                    if(flash)
                    {
                        flash->spawntype = SPAWN_TYPE_FLASH;
                        execute_onspawn_script(flash);
                    }
                }
                //end of if #0531
            }
            else if((self->modeldata.nopassiveblock || self->modeldata.type == TYPE_PLAYER) &&  // can block by itself
                    self->blocking &&  // of course he must be blocking
                    ((self->modeldata.guardpoints.max == 0) || (self->modeldata.guardpoints.max > 0 && self->modeldata.guardpoints.current > 0)) &&
                    !((self->direction == e->direction && self->modeldata.blockback < 1) || self->frozen) &&   // Can't block if facing the wrong direction (unless blockback flag is enabled) or frozen in the block animation or opponent is a projectile
                    attack->no_block <= self->defense[attack->attack_type].blockpower &&    // Make sure you are actually blocking and that the attack is blockable
                    (!self->modeldata.thold ||
                     (self->modeldata.thold > 0 &&
                      self->modeldata.thold > force)) &&
                    (!self->defense[attack->attack_type].blockthreshold ||                   //Specific attack type threshold.
                     (self->defense[attack->attack_type].blockthreshold > force)))
            {
                // Only block if the attack is less than the players threshold
                //execute the didhit script
                execute_didhit_script(e, self, attack, 1);
                if(self->modeldata.guardpoints.max > 0)
                {
                    self->modeldata.guardpoints.current = self->modeldata.guardpoints.current - attack->guardcost;
                }
                ++current_anim->animhits;
                didblock = 1;    // Used for when playing the block.wav sound

                if(self->modeldata.blockpain && self->modeldata.blockpain <= force && self->animation == self->modeldata.animation[ANI_BLOCK]) //Blockpain 1 and in block animation?
                {
                    set_blockpain(self, attack->attack_type, 0);
                }
                execute_didblock_script(self, e, attack);

                // Spawn a flash
                if(!attack->no_flash)
                {
                    if(!self->modeldata.noatflash)
                    {
                        if(attack->blockflash >= 0)
                        {
                            flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, attack->blockflash, NULL);    // custom bflash
                        }
                        else
                        {
                            flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, ent_list[i]->modeldata.bflash, NULL);    // New block flash that can be smaller
                        }
                    }
                    else
                    {
                        flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, self->modeldata.bflash, NULL);
                    }
                    //ent_default_init(flash); // initiliaze this because there're no default values now
                    if(flash)
                    {
                        flash->spawntype = SPAWN_TYPE_FLASH;
                        execute_onspawn_script(flash);
                    }
                }
            }
            else if(self->animation->counterrange &&	// Has counter range?
                    (self->animpos >= self->animation->counterrange->frame.min && self->animpos <= self->animation->counterrange->frame.max) &&  // Current frame within counter range frames?
                    !self->frozen &&
                    (self->energy_status.health_current > force || (self->energy_status.health_current-force <= 0 && (self->animation->counterrange->condition == COUNTERACTION_CONDITION_ALWAYS_RAGE))) &&   // Rage or not?
                    // counterrange conditions
                    ( (self->animation->counterrange->condition == COUNTERACTION_CONDITION_ALWAYS) || (self->animation->counterrange->condition == COUNTERACTION_CONDITION_ALWAYS_RAGE) ||
                    (self->animation->counterrange->condition == COUNTERACTION_CONDITION_HOSTILE && e->modeldata.type & them) ||
                    (self->animation->counterrange->condition == COUNTERACTION_CONDITION_HOSTILE_FRONT_NOFREEZE && !attack->no_block && !(self->direction == e->direction) && !attack->freeze ) )

                    ) {

                    // Take damage from attack?
                    if(self->animation->counterrange->damaged == COUNTERACTION_DAMAGE_NORMAL)
                    {
                        if (self->energy_status.health_current-force <= 0)
                        {
                            // White Dragon: commented the alternative method
                            /*s_collision_attack atk;

                            atk = emptyattack;
                            atk.attack_force = force;
                            atk.attack_drop = attack->attack_drop;
                            atk.attack_type = attack->attack_type;

                            atk.dropv.y = (float)DEFAULT_ATK_DROPV_Y;
                            atk.dropv.x = (float)DEFAULT_ATK_DROPV_X;
                            atk.dropv.z = (float)DEFAULT_ATK_DROPV_Z;

                            if (e) self->takedamage(e, &atk, 0);
                            else self->takedamage(self, &atk, 0);

                            self = temp;
                            return;*/

                            self->energy_status.health_current = 1; // rage
                        }
                        else
                        {
                            self->energy_status.health_current -= force;
                        }
                    }

                    current_follow_id = animfollows[self->animation->followup.animation - 1];
                    if(validanim(self, current_follow_id))
                    {
                        if(!self->modeldata.animation[current_follow_id]->attackone)
                        {
                            self->modeldata.animation[current_follow_id]->attackone = self->animation->attackone;
                        }
                        ent_set_anim(self, current_follow_id, 0);
                        self->attack_id_incoming = current_attack_id;
                    }

                    if(!attack->no_flash)
                    {
                        if(!self->modeldata.noatflash)
                        {
                            if(attack->blockflash >= 0)
                            {
                                flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, attack->blockflash, NULL);    // custom bflash
                            }
                            else
                            {
                                flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, ent_list[i]->modeldata.bflash, NULL);    // New block flash that can be smaller
                            }
                        }
                        else
                        {
                            flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, self->modeldata.bflash, NULL);
                        }
                        //ent_default_init(flash); // initiliaze this because there're no default values now
                        if(flash)
                        {
                            flash->spawntype = SPAWN_TYPE_FLASH;
                            execute_onspawn_script(flash);
                        }
                    }
            }
            else if(self->takedamage(e, attack, 0))
            {
                // Didn't block so go ahead and take the damage
                execute_didhit_script(e, self, attack, 0);
                ++e->animation->animhits;

                e->lasthit = self;

                // Spawn a flash
                if(!attack->no_flash)
                {
                    if(!self->modeldata.noatflash)
                    {
                        if(attack->hitflash >= 0)
                        {
                            flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, attack->hitflash, NULL);
                        }
                        else
                        {
                            flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, e->modeldata.flash, NULL);
                        }
                    }
                    else
                    {
                        flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, self->modeldata.flash, NULL);
                    }
                    if(flash)
                    {
                        flash->spawntype = SPAWN_TYPE_FLASH;
                        execute_onspawn_script(flash);
                    }
                }
                topowner->combotime = _time + combodelay; // well, add to its owner's combo

                if(e->pausetime < _time || (inair(e) && !equalairpause))        // if equalairpause is set, inair(e) is nolonger a condition for extra pausetime
                {
                    // Adds pause to the current animation
                    e->toss_time += attack->pause_add;      // So jump height pauses in midair
                    e->nextmove += attack->pause_add;      // xdir, zdir
                    e->nextanim += attack->pause_add;       //Pause animation for a bit
                    e->nextthink += attack->pause_add;      // So anything that auto moves will pause
                    e->pausetime = _time + attack->pause_add ; //UT: temporary solution
                }

                self->toss_time += attack->pause_add;       // So jump height pauses in midair
                self->nextmove += attack->pause_add;      // xdir, zdir
                self->nextanim += attack->pause_add;        //Pause animation for a bit
                self->nextthink += attack->pause_add;       // So anything that auto moves will pause

            }
            else
            {
                didhit = 0;
                continue;
            }
            // end of if #053

            // if #054
            if(flash)
            {
                if(flash->modeldata.toflip)
                {
                    flash->direction = (e->position.x > self->position.x);    // Now the flash will flip depending on which side the attacker is on
                }

                flash->base = lasthit.position.y;
                flash->autokill = 2;
            }//end of if #054

            // 2007 3 24, hmm, def should be like this
            if(didblock && !def)
            {
                def = self;
            }
            //if #055
            if((e->animation->followup.animation) && // follow up?
                    (!e->animation->counterrange) && // This isn't suppossed to be a counter, right?
                    ((e->animation->followup.condition < FOLLOW_CONDITION_HOSTILE) || (self->modeldata.type & e->modeldata.hostile)) &&                                // Does type matter?
                    ((e->animation->followup.condition < FOLLOW_CONDITION_HOSTILE_NOKILL_NOBLOCK) || ((self->energy_status.health_current > 0) && !didblock)) &&                             // check if health or not blocking matters
                    ((e->animation->followup.condition < FOLLOW_CONDITION_HOSTILE_NOKILL_NOBLOCK_NOGRAB) || ((self->energy_status.health_current > 0) && !didblock && cangrab(e, self)) ) && // check if nograb matters
                    ((e->animation->followup.condition < FOLLOW_CONDITION_HOSTILE_NOKILL_BLOCK) || ((self->energy_status.health_current > 0) && didblock))                                   // check if health or blocking matters
              )
            {
                current_follow_id = animfollows[e->animation->followup.animation - 1];
                if(validanim(e, current_follow_id))
                {
                    if(!e->modeldata.animation[current_follow_id]->attackone)
                    {
                        e->modeldata.animation[current_follow_id]->attackone = e->animation->attackone;
                    }
                    ent_set_anim(e, current_follow_id, 1);          // Then go to it!
                }
                //followed = 1; // quit loop, animation is changed
            }//end of if #055

            self->attack_id_incoming = current_attack_id;
            if(self == def)
            {
                self->blocking = didblock;    // yeah, if get hit, stop blocking
            }

            //2011/11/24 UT: move the pain_time logic here,
            // because block needs this as well otherwise blockratio causes instant death
            self->pain_time = _time + (attack->pain_time ? attack->pain_time : (GAME_SPEED / 5));
            self->nextattack = 0; // reset this, make it easier to fight back
        }//end of if #05
        self = temp;

    } // end of for


    // if ###
    if(didhit)
    {
        if(current_anim->energycost)
        {
            // well, dont check player or not - UTunnels. TODO: take care of that healthcheat
            if(e == topowner && current_anim->energycost->cost > 0 && nocost && !healthcheat)
            {
                e->tocost = 1;    // Set flag so life is subtracted when animation is finished
            }
            else if(e != topowner && current_anim->energycost->cost > 0 && nocost && !healthcheat && !e->tocost) // if it is not top, then must be a shot
            {
                if(current_anim->energycost->mponly != COST_TYPE_MP_THEN_HP && topowner->energy_status.mp_current > 0)
                {
                    topowner->energy_status.mp_current -= current_anim->energycost->cost;
                    if(topowner->energy_status.mp_current < 0)
                    {
                        topowner->energy_status.mp_current = 0;
                    }
                }
                else
                {
                    topowner->energy_status.health_current -= current_anim->energycost->cost;
                    if(topowner->energy_status.health_current <= 0)
                    {
                        topowner->energy_status.health_current = 1;
                    }
                }

                e->tocost = 1;    // Little backwards, but set to 1 so cost doesn't get subtracted multiple times
            }
        }

        // New blocking checks
        //04/27/2008 Damon Caskey: Added checks for defense property specfic blockratio and type. Could probably use some cleaning.
        if(didblock && level->nohurt == DAMAGE_FROM_ENEMY_ON)
        {
            if(blockratio || def->defense[attack->attack_type].blockratio) // Is damage reduced?
            {
                if (def->defense[attack->attack_type].blockratio)                       //Typed blockratio?
                {
                    force = (int)(force * def->defense[attack->attack_type].blockratio);
                }
                else                                                                              //No typed. Use static block ratio.
                {
                    force = force / 4;
                }

                /*
                Block type handling. For backward compatibility we will use BLOCK_TYPE_MP_FIRST regardless
                of defense setting if author has enabled mpblock. Otherwise the defender's blocktype
                for incoming attack type will be used. Once this is determined, we will apply the
                appropriate blocktype accordingly.
                */
                blocktype = mpblock ? BLOCK_TYPE_MP_FIRST : def->defense[attack->attack_type].blocktype;

                switch (blocktype)
                {
                    case BLOCK_TYPE_HP:
                        //Do nothing. This is so modders can overidde energycost mponly 1 with health only.
                        break;

                    case BLOCK_TYPE_MP_ONLY:

                        def->energy_status.mp_current -= force;
                        force = 0;

                        if(def->energy_status.mp_current < 0)
                        {
                            def->energy_status.mp_current = 0;
                        }

                    case BLOCK_TYPE_MP_FIRST:

                        def->energy_status.mp_current -= force;

                        /* If there isn't enough MP to cover force, subtract remaining MP from force and set MP to 0 */
                        if(def->energy_status.mp_current < 0)
                        {
                            force = -def->energy_status.mp_current;
                            def->energy_status.mp_current = 0;
                        }
                        else
                        {
                            force = 0;
                        }

                    case BLOCK_TYPE_BOTH:

                        def->energy_status.mp_current -= force;

                        if(def->energy_status.mp_current < 0)
                        {
                            def->energy_status.mp_current = 0;
                        }
                }

                if(force < def->energy_status.health_current)                    // If an attack won't deal damage, this line won't do anything anyway.
                {
                    def->energy_status.health_current -= force;
                }
                else if(nochipdeath)                       // No chip deaths?
                {
                    def->energy_status.health_current = 1;
                }
                else
                {
                    temp = self;
                    self = def;
                    self->takedamage(e, attack, 0);           // Must be a fatal attack, then!
                    self = temp;
                }
            }
        }

        if(!didblock)
        {
            topowner->rush.time = _time + (GAME_SPEED * rush[1]);
            topowner->rush.count.current++;
            if(topowner->rush.count.current > topowner->rush.count.max && topowner->rush.count.current > 1)
            {
                topowner->rush.count.max = topowner->rush.count.current;
            }
        }

        if(didblock)
        {
            if(attack->blocksound >= 0)
            {
                sound_play_sample(attack->blocksound, 0, savedata.effectvol, savedata.effectvol, 100);    // New custom block sound effect
            }
            else if(SAMPLE_BLOCK >= 0)
            {
                sound_play_sample(SAMPLE_BLOCK, 0, savedata.effectvol, savedata.effectvol, 100);    // Default block sound effect
            }
        }
        else if(e->projectile > 0 && SAMPLE_INDIRECT >= 0)
        {
            sound_play_sample(SAMPLE_INDIRECT, 0, savedata.effectvol, savedata.effectvol, 100);
        }
        else if(attack->hitsound >= 0)
        {
            t = 100 - (noslowfx ? 0 : (force - 5));
            if(t > 100)
            {
                t = 100;
            }
            else if(t < 60)
            {
                t = 60;
            }
            sound_play_sample(attack->hitsound, 0, savedata.effectvol, savedata.effectvol, t);
        }

        if(e->remove_on_attack)
        {
            kill_entity(e);
        }
    }//end of if ###
#undef followed
}

official.attacking_enum:
typedef enum
{
    ATTACKING_INACTIVE,
    ATTACKING_PREPARED,
    ATTACKING_ACTIVE
    // Next should be 4, 8, ... for bitwise evaluations.
} e_attacking_state;

physical.do_attack:
void do_attack(entity *e)
{
    int them;
    int i, t;
    int force = 0;
    e_blocktype blocktype;
    entity *temp            = NULL;
    entity *flash           = NULL;    // Used so new flashes can be used
    entity *def             = NULL;
    entity *topowner        = NULL;
    entity *otherowner      = NULL;
    entity *target          = NULL;
    s_anim      *current_anim;
    s_collision_attack *attack = NULL;
    int didhit              = 0;
    int didblock            = 0;    // So a different sound effect can be played when an attack is blocked
    int current_attack_id;
    int current_follow_id   = 0;
    //int hit_detected        = 0;    // Has a hit been detected?


#define followed (current_anim!=e->animation)
    static unsigned int new_attack_id = 1;
    int fdefense_blockthreshold; //max damage that can be blocked for attack type.

    // Can't get hit after this
    if(level_completed)
    {
        return;
    }

    topowner = e; // trace the top owner, for projectile combo checking :)
    while(topowner->owner)
    {
        topowner = topowner->owner;
    }

    if(e->projectile > 0)
    {
        them = e->modeldata.projectilehit;
    }
    else
    {
        them = e->modeldata.candamage;
    }

    // Every attack gets a unique ID to make sure no one
    // gets hit more than once by the same attack
    current_attack_id = e->attack_id_outgoing;

    if(!current_attack_id)
    {
        ++new_attack_id;
        if(new_attack_id == 0)
        {
            new_attack_id = 1;
        }
        e->attack_id_outgoing = current_attack_id = new_attack_id;
    }


    current_anim = e->animation;

    for(i = 0; i < ent_max && !followed; i++)
    {
        target = ent_list[i];

        if(!target->exists)
        {
            continue;
        }

        // Check collision. If a collision
        // is found, lasthit the impacting
        // collision pointers are also
        // populated into lasthit, which
        // we will use below.
        if(!checkhit(e, target))
        {
            continue;
        }

        attack = lasthit.attack;
        fdefense_blockthreshold = (int)self->defense[attack->attack_type].blockthreshold; //max damage that can be blocked for attack type.
        force = attack->attack_force;

        // Verify target is alive.
        if(target->dead)
        {
            continue;
        }

        // Verify target is invincible,
        // or attack type is an item.
        // This is too allow item collection
        // even while invincible.
        if(target->invincible)
        {
            if(attack->attack_type != ATK_ITEM)
            {
                continue;
            }
        }

        // If attack is set to only hit
        // one entity at a _time (attackone),
        // we verify last hit (lasthit) is
        // set. If last hit is set and
        // differs from current target,
        // then we are trying to hit
        // another entity and should exit.
        if(current_anim->attackone)
        {
            if(e->lasthit)
            {
                if(target != e->lasthit)
                {
                    continue;
                }
            }
        }

        // Verify target has a match to
        // projectile hit or can damage.
        if(!(target->modeldata.type & them))
        {
            continue;
        }

        // Pain _time must have expired.
        // This is to allow reasonable delay
        // between hits so engine will not
        // run hit on every update.
        if(target->pain_time >= _time)
        {
            continue;
        }

        // Target takedamage flag
        // must be set.
        if(!target->takedamage)
        {
            continue;
        }

        // Attack IDs must be different.
        if(target->attack_id_incoming == current_attack_id && !attack->ignore_attack_id)
        {
            continue;
        }

        // Target laying down? Exit if
        // attack only hits standing targets.
        if(target->takeaction == common_lie)
        {
            if(attack->otg == OTG_NONE)
            {
                continue;
            }
        }

        // Target NOT laying down? Exit if
        // attack only hits grounded targets.
        if(target->takeaction != common_lie)
        {
            if(attack->otg == OTG_GROUND_ONLY)
            {
                continue;
            }
        }

        // If in the air, then check the juggle cost.
        if(inair(target))
        {
            if(attack->jugglecost > target->modeldata.jugglepoints.current)
            {
                continue;
            }
        }

        temp = self;
        self = target;

        // Execute the doattack scripts so author can set take action
        // before the hit code below does.
        execute_ondoattack_script(self, e, attack, EXCHANGE_RECIPIANT, current_attack_id);
        execute_ondoattack_script(e, self, attack, EXCHANGE_CONFERRER, current_attack_id);

        // 2010-12-31
        // Damon V. Caskey

        // If lasthit.confirm is not true, it must have been turned off by the author; almost
        // certainly with the ondoattack event scripts above. Skip the engine's
        // default hit handling below. Useful for scripting parry systems, alternate blocking,
        // or other custom collision events.
        if(lasthit.confirm)
        {
            didhit = 1;
        }
        else
        {
            // By White Dragon
            // This line: self = temp; is the fix for
            // !lasthit.confirm bug. Without it when
            // active lasthitc 0 the damagetaker has
            // weird speedy effect.
            self = temp;
            continue;
        }

        otherowner = self; // trace top owner for opponent
        while(otherowner->owner)
        {
            otherowner = otherowner->owner;
        }

        //if #01, if they are fired by the same owner, or the owner itself
        if(topowner == otherowner)
        {
            didhit = 0;
        }

        //if #02 , ground missle checking, and bullets wont hit each other
        if( (e->owner && self->owner) ||
                (e->modeldata.ground && inair(e))  )
        {
            didhit = 0;
        }//end of if #02

        //if #05,   blocking code section
        if(didhit)
        {
            if(attack->attack_type == ATK_ITEM)
            {
                do_item_script(self, e);

                didfind_item(e);
                return;
            }
            //if #051
            if(self->toexplode == 1)
            {
                self->toexplode = 2;    // Used so the bomb type entity explodes when hit
            }
            //if #052
            if(e->toexplode == 1)
            {
                e->toexplode = 2;    // Used so the bomb type entity explodes when hitting
            }

            if(inair(self))
            {
                self->modeldata.jugglepoints.current = self->modeldata.jugglepoints.current - attack->jugglecost;    //reduce available juggle points.
            }

            //if #053
            if( !self->modeldata.nopassiveblock && // cant block by itself
                    validanim(self, ANI_BLOCK) && // of course, move it here to avoid some useless checking
                    ((self->modeldata.guardpoints.max == 0) || (self->modeldata.guardpoints.max > 0 && self->modeldata.guardpoints.current > 0)) &&
                    !(self->link ||
                      inair(self) ||
                      self->frozen ||
                      (self->direction == e->direction && self->modeldata.blockback < 1) ||                       // Can't block an attack that is from behind unless blockback flag is enabled
                      (!self->idling && self->attacking != ATTACKING_INACTIVE)) &&                                                 // Can't block if busy, attack <0 means the character is preparing to attack, he can block during this time
                    attack->no_block <= self->defense[attack->attack_type].blockpower &&       // If unblockable, will automatically hit
                    (rand32()&self->modeldata.blockodds) == 1 && // Randomly blocks depending on blockodds (1 : blockodds ratio)
                    (!self->modeldata.thold || (self->modeldata.thold > 0 && self->modeldata.thold > force)) &&
                    (!fdefense_blockthreshold ||                                                                //Specific attack type threshold.
                     (fdefense_blockthreshold > force)))
            {
                //execute the didhit script
                execute_didhit_script(e, self, attack, 1);
                self->takeaction = common_block;
                set_blocking(self);
                self->velocity.x = self->velocity.z = 0;
                ent_set_anim(self, ANI_BLOCK, 0);

                execute_didblock_script(self, e, attack);

                if(self->modeldata.guardpoints.max > 0)
                {
                    self->modeldata.guardpoints.current = self->modeldata.guardpoints.current - attack->guardcost;
                }
                ++current_anim->animhits;
                didblock = 1;    // Used for when playing the block.wav sound
                // Spawn a flash
                //if #0531
                if(!attack->no_flash)
                {
                    if(!self->modeldata.noatflash)
                    {
                        if(attack->blockflash >= 0)
                        {
                            flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, attack->blockflash, NULL);    // custom bflash
                        }
                        else
                        {
                            flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, ent_list[i]->modeldata.bflash, NULL);    // New block flash that can be smaller
                        }
                    }
                    else
                    {
                        flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, self->modeldata.bflash, NULL);
                    }
                    //ent_default_init(flash); // initiliaze this because there're no default values now

                    if(flash)
                    {
                        flash->spawntype = SPAWN_TYPE_FLASH;
                        execute_onspawn_script(flash);
                    }
                }
                //end of if #0531
            }
            else if((self->modeldata.nopassiveblock || self->modeldata.type == TYPE_PLAYER) &&  // can block by itself
                    self->blocking &&  // of course he must be blocking
                    ((self->modeldata.guardpoints.max == 0) || (self->modeldata.guardpoints.max > 0 && self->modeldata.guardpoints.current > 0)) &&
                    !((self->direction == e->direction && self->modeldata.blockback < 1) || self->frozen) &&   // Can't block if facing the wrong direction (unless blockback flag is enabled) or frozen in the block animation or opponent is a projectile
                    attack->no_block <= self->defense[attack->attack_type].blockpower &&    // Make sure you are actually blocking and that the attack is blockable
                    (!self->modeldata.thold ||
                     (self->modeldata.thold > 0 &&
                      self->modeldata.thold > force)) &&
                    (!self->defense[attack->attack_type].blockthreshold ||                   //Specific attack type threshold.
                     (self->defense[attack->attack_type].blockthreshold > force)))
            {
                // Only block if the attack is less than the players threshold
                //execute the didhit script
                execute_didhit_script(e, self, attack, 1);
                if(self->modeldata.guardpoints.max > 0)
                {
                    self->modeldata.guardpoints.current = self->modeldata.guardpoints.current - attack->guardcost;
                }
                ++current_anim->animhits;
                didblock = 1;    // Used for when playing the block.wav sound

                if(self->modeldata.blockpain && self->modeldata.blockpain <= force && self->animation == self->modeldata.animation[ANI_BLOCK]) //Blockpain 1 and in block animation?
                {
                    set_blockpain(self, attack->attack_type, 0);
                }
                execute_didblock_script(self, e, attack);

                // Spawn a flash
                if(!attack->no_flash)
                {
                    if(!self->modeldata.noatflash)
                    {
                        if(attack->blockflash >= 0)
                        {
                            flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, attack->blockflash, NULL);    // custom bflash
                        }
                        else
                        {
                            flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, ent_list[i]->modeldata.bflash, NULL);    // New block flash that can be smaller
                        }
                    }
                    else
                    {
                        flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, self->modeldata.bflash, NULL);
                    }
                    //ent_default_init(flash); // initiliaze this because there're no default values now
                    if(flash)
                    {
                        flash->spawntype = SPAWN_TYPE_FLASH;
                        execute_onspawn_script(flash);
                    }
                }
            }
            else if(self->animation->counterrange &&	// Has counter range?
                    (self->animpos >= self->animation->counterrange->frame.min && self->animpos <= self->animation->counterrange->frame.max) &&  // Current frame within counter range frames?
                    !self->frozen &&
                    (self->energy_status.health_current > force || (self->energy_status.health_current-force <= 0 && (self->animation->counterrange->condition == COUNTERACTION_CONDITION_ALWAYS_RAGE))) &&   // Rage or not?
                    // counterrange conditions
                    ( (self->animation->counterrange->condition == COUNTERACTION_CONDITION_ALWAYS) || (self->animation->counterrange->condition == COUNTERACTION_CONDITION_ALWAYS_RAGE) ||
                    (self->animation->counterrange->condition == COUNTERACTION_CONDITION_HOSTILE && e->modeldata.type & them) ||
                    (self->animation->counterrange->condition == COUNTERACTION_CONDITION_HOSTILE_FRONT_NOFREEZE && !attack->no_block && !(self->direction == e->direction) && !attack->freeze ) )

                    ) {

                    // Take damage from attack?
                    if(self->animation->counterrange->damaged == COUNTERACTION_DAMAGE_NORMAL)
                    {
                        if (self->energy_status.health_current-force <= 0)
                        {
                            // White Dragon: commented the alternative method
                            /*s_collision_attack atk;

                            atk = emptyattack;
                            atk.attack_force = force;
                            atk.attack_drop = attack->attack_drop;
                            atk.attack_type = attack->attack_type;

                            atk.dropv.y = (float)DEFAULT_ATK_DROPV_Y;
                            atk.dropv.x = (float)DEFAULT_ATK_DROPV_X;
                            atk.dropv.z = (float)DEFAULT_ATK_DROPV_Z;

                            if (e) self->takedamage(e, &atk, 0);
                            else self->takedamage(self, &atk, 0);

                            self = temp;
                            return;*/

                            self->energy_status.health_current = 1; // rage
                        }
                        else
                        {
                            self->energy_status.health_current -= force;
                        }
                    }

                    current_follow_id = animfollows[self->animation->followup.animation - 1];
                    if(validanim(self, current_follow_id))
                    {
                        if(!self->modeldata.animation[current_follow_id]->attackone)
                        {
                            self->modeldata.animation[current_follow_id]->attackone = self->animation->attackone;
                        }
                        ent_set_anim(self, current_follow_id, 0);
                        self->attack_id_incoming = current_attack_id;
                    }

                    if(!attack->no_flash)
                    {
                        if(!self->modeldata.noatflash)
                        {
                            if(attack->blockflash >= 0)
                            {
                                flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, attack->blockflash, NULL);    // custom bflash
                            }
                            else
                            {
                                flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, ent_list[i]->modeldata.bflash, NULL);    // New block flash that can be smaller
                            }
                        }
                        else
                        {
                            flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, self->modeldata.bflash, NULL);
                        }
                        //ent_default_init(flash); // initiliaze this because there're no default values now
                        if(flash)
                        {
                            flash->spawntype = SPAWN_TYPE_FLASH;
                            execute_onspawn_script(flash);
                        }
                    }
            }
            else if(self->takedamage(e, attack, 0))
            {
                // Didn't block so go ahead and take the damage
                execute_didhit_script(e, self, attack, 0);
                ++e->animation->animhits;

                e->lasthit = self;

                // Spawn a flash
                if(!attack->no_flash)
                {
                    if(!self->modeldata.noatflash)
                    {
                        if(attack->hitflash >= 0)
                        {
                            flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, attack->hitflash, NULL);
                        }
                        else
                        {
                            flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, e->modeldata.flash, NULL);
                        }
                    }
                    else
                    {
                        flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, self->modeldata.flash, NULL);
                    }
                    if(flash)
                    {
                        flash->spawntype = SPAWN_TYPE_FLASH;
                        execute_onspawn_script(flash);
                    }
                }
                topowner->combotime = _time + combodelay; // well, add to its owner's combo

                if(e->pausetime < _time || (inair(e) && !equalairpause))        // if equalairpause is set, inair(e) is nolonger a condition for extra pausetime
                {
                    // Adds pause to the current animation
                    e->toss_time += attack->pause_add;      // So jump height pauses in midair
                    e->nextmove += attack->pause_add;      // xdir, zdir
                    e->nextanim += attack->pause_add;       //Pause animation for a bit
                    e->nextthink += attack->pause_add;      // So anything that auto moves will pause
                    e->pausetime = _time + attack->pause_add ; //UT: temporary solution
                }

                self->toss_time += attack->pause_add;       // So jump height pauses in midair
                self->nextmove += attack->pause_add;      // xdir, zdir
                self->nextanim += attack->pause_add;        //Pause animation for a bit
                self->nextthink += attack->pause_add;       // So anything that auto moves will pause

            }
            else
            {
                didhit = 0;
                continue;
            }
            // end of if #053

            // if #054
            if(flash)
            {
                if(flash->modeldata.toflip)
                {
                    flash->direction = (e->position.x > self->position.x);    // Now the flash will flip depending on which side the attacker is on
                }

                flash->base = lasthit.position.y;
                flash->autokill = 2;
            }//end of if #054

            // 2007 3 24, hmm, def should be like this
            if(didblock && !def)
            {
                def = self;
            }
            //if #055
            if((e->animation->followup.animation) && // follow up?
                    (!e->animation->counterrange) && // This isn't suppossed to be a counter, right?
                    ((e->animation->followup.condition < FOLLOW_CONDITION_HOSTILE) || (self->modeldata.type & e->modeldata.hostile)) &&                                // Does type matter?
                    ((e->animation->followup.condition < FOLLOW_CONDITION_HOSTILE_NOKILL_NOBLOCK) || ((self->energy_status.health_current > 0) && !didblock)) &&                             // check if health or not blocking matters
                    ((e->animation->followup.condition < FOLLOW_CONDITION_HOSTILE_NOKILL_NOBLOCK_NOGRAB) || ((self->energy_status.health_current > 0) && !didblock && cangrab(e, self)) ) && // check if nograb matters
                    ((e->animation->followup.condition < FOLLOW_CONDITION_HOSTILE_NOKILL_BLOCK) || ((self->energy_status.health_current > 0) && didblock))                                   // check if health or blocking matters
              )
            {
                current_follow_id = animfollows[e->animation->followup.animation - 1];
                if(validanim(e, current_follow_id))
                {
                    if(!e->modeldata.animation[current_follow_id]->attackone)
                    {
                        e->modeldata.animation[current_follow_id]->attackone = e->animation->attackone;
                    }
                    ent_set_anim(e, current_follow_id, 1);          // Then go to it!
                }
                //followed = 1; // quit loop, animation is changed
            }//end of if #055

            self->attack_id_incoming = current_attack_id;
            if(self == def)
            {
                self->blocking = didblock;    // yeah, if get hit, stop blocking
            }

            //2011/11/24 UT: move the pain_time logic here,
            // because block needs this as well otherwise blockratio causes instant death
            self->pain_time = _time + (attack->pain_time ? attack->pain_time : (GAME_SPEED / 5));
            self->nextattack = 0; // reset this, make it easier to fight back
        }//end of if #05
        self = temp;

    } // end of for


    // if ###
    if(didhit)
    {
        if(current_anim->energycost)
        {
            // well, dont check player or not - UTunnels. TODO: take care of that healthcheat
            if(e == topowner && current_anim->energycost->cost > 0 && nocost && !healthcheat)
            {
                e->tocost = 1;    // Set flag so life is subtracted when animation is finished
            }
            else if(e != topowner && current_anim->energycost->cost > 0 && nocost && !healthcheat && !e->tocost) // if it is not top, then must be a shot
            {
                if(current_anim->energycost->mponly != COST_TYPE_MP_THEN_HP && topowner->energy_status.mp_current > 0)
                {
                    topowner->energy_status.mp_current -= current_anim->energycost->cost;
                    if(topowner->energy_status.mp_current < 0)
                    {
                        topowner->energy_status.mp_current = 0;
                    }
                }
                else
                {
                    topowner->energy_status.health_current -= current_anim->energycost->cost;
                    if(topowner->energy_status.health_current <= 0)
                    {
                        topowner->energy_status.health_current = 1;
                    }
                }

                e->tocost = 1;    // Little backwards, but set to 1 so cost doesn't get subtracted multiple times
            }
        }

        // New blocking checks
        //04/27/2008 Damon Caskey: Added checks for defense property specfic blockratio and type. Could probably use some cleaning.
        if(didblock && level->nohurt == DAMAGE_FROM_ENEMY_ON)
        {
            if(blockratio || def->defense[attack->attack_type].blockratio) // Is damage reduced?
            {
                if (def->defense[attack->attack_type].blockratio)                       //Typed blockratio?
                {
                    force = (int)(force * def->defense[attack->attack_type].blockratio);
                }
                else                                                                              //No typed. Use static block ratio.
                {
                    force = force / 4;
                }

                /*
                Block type handling. For backward compatibility we will use BLOCK_TYPE_MP_FIRST regardless
                of defense setting if author has enabled mpblock. Otherwise the defender's blocktype
                for incoming attack type will be used. Once this is determined, we will apply the
                appropriate blocktype accordingly.
                */
                blocktype = mpblock ? BLOCK_TYPE_MP_FIRST : def->defense[attack->attack_type].blocktype;

                switch (blocktype)
                {
                    case BLOCK_TYPE_HP:
                        //Do nothing. This is so modders can overidde energycost mponly 1 with health only.
                        break;

                    case BLOCK_TYPE_MP_ONLY:

                        def->energy_status.mp_current -= force;
                        force = 0;

                        if(def->energy_status.mp_current < 0)
                        {
                            def->energy_status.mp_current = 0;
                        }

                    case BLOCK_TYPE_MP_FIRST:

                        def->energy_status.mp_current -= force;

                        /* If there isn't enough MP to cover force, subtract remaining MP from force and set MP to 0 */
                        if(def->energy_status.mp_current < 0)
                        {
                            force = -def->energy_status.mp_current;
                            def->energy_status.mp_current = 0;
                        }
                        else
                        {
                            force = 0;
                        }

                    case BLOCK_TYPE_BOTH:

                        def->energy_status.mp_current -= force;

                        if(def->energy_status.mp_current < 0)
                        {
                            def->energy_status.mp_current = 0;
                        }
                }

                if(force < def->energy_status.health_current)                    // If an attack won't deal damage, this line won't do anything anyway.
                {
                    def->energy_status.health_current -= force;
                }
                else if(nochipdeath)                       // No chip deaths?
                {
                    def->energy_status.health_current = 1;
                }
                else
                {
                    temp = self;
                    self = def;
                    self->takedamage(e, attack, 0);           // Must be a fatal attack, then!
                    self = temp;
                }
            }
        }

        if(!didblock)
        {
            topowner->rush.time = _time + (GAME_SPEED * rush[1]);
            topowner->rush.count.current++;
            if(topowner->rush.count.current > topowner->rush.count.max && topowner->rush.count.current > 1)
            {
                topowner->rush.count.max = topowner->rush.count.current;
            }
        }

        if(didblock)
        {
            if(attack->blocksound >= 0)
            {
                sound_play_sample(attack->blocksound, 0, savedata.effectvol, savedata.effectvol, 100);    // New custom block sound effect
            }
            else if(SAMPLE_BLOCK >= 0)
            {
                sound_play_sample(SAMPLE_BLOCK, 0, savedata.effectvol, savedata.effectvol, 100);    // Default block sound effect
            }
        }
        else if(e->projectile > 0 && SAMPLE_INDIRECT >= 0)
        {
            sound_play_sample(SAMPLE_INDIRECT, 0, savedata.effectvol, savedata.effectvol, 100);
        }
        else if(attack->hitsound >= 0)
        {
            t = 100 - (noslowfx ? 0 : (force - 5));
            if(t > 100)
            {
                t = 100;
            }
            else if(t < 60)
            {
                t = 60;
            }
            sound_play_sample(attack->hitsound, 0, savedata.effectvol, savedata.effectvol, t);
        }

        if(e->remove_on_attack)
        {
            kill_entity(e);
        }
    }//end of if ###
#undef followed
}

physical.attacking_enum:
typedef enum
{
    ATTACKING_INACTIVE,
    ATTACKING_PREPARED,
    ATTACKING_ACTIVE
    // Next should be 4, 8, ... for bitwise evaluations.
} e_attacking_state;

lns.do_attack:
void do_attack(entity *e)
{
    int them;
    int i, t;
    int force = 0;
    e_blocktype blocktype;
    entity *temp            = NULL;
    entity *flash           = NULL;    // Used so new flashes can be used
    entity *def             = NULL;
    entity *topowner        = NULL;
    entity *otherowner      = NULL;
    entity *target          = NULL;
    s_anim      *current_anim;
    s_collision_attack *attack = NULL;
    int didhit              = 0;
    int didblock            = 0;    // So a different sound effect can be played when an attack is blocked
    int current_attack_id;
    int current_follow_id   = 0;
    //int hit_detected        = 0;    // Has a hit been detected?


#define followed (current_anim!=e->animation)
    static unsigned int new_attack_id = 1;
    int fdefense_blockthreshold; //max damage that can be blocked for attack type.

    // Can't get hit after this
    // if(level_completed)
    // {
    //     return;
    // }

    topowner = e; // trace the top owner, for projectile combo checking :)
    while(topowner->owner)
    {
        topowner = topowner->owner;
    }

    if(e->projectile > 0)
    {
        them = e->modeldata.projectilehit;
    }
    else
    {
        them = e->modeldata.candamage;
    }

    // Every attack gets a unique ID to make sure no one
    // gets hit more than once by the same attack
    current_attack_id = e->attack_id_outgoing;

    if(!current_attack_id)
    {
        ++new_attack_id;
        if(new_attack_id == 0)
        {
            new_attack_id = 1;
        }
        e->attack_id_outgoing = current_attack_id = new_attack_id;
	//printf("Attack_id %d \n", new_attack_id); //TAG_YO
    }


    current_anim = e->animation;

    for(i = 0; i < ent_max && !followed; i++)
    {
        target = ent_list[i];

        if(!target->exists)
        {
            continue;
        }

        // avoid players taking damage once the level is completed
        if(level_completed && (target->modeldata.type & TYPE_PLAYER))
        {
            continue;
        }

        // Check collision. If a collision
        // is found, lasthit the impacting
        // collision pointers are also
        // populated into lasthit, which
        // we will use below.
        if(!checkhit(e, target))
        {
            continue;
        }

        attack = lasthit.attack;
        fdefense_blockthreshold = (int)self->defense[attack->attack_type].blockthreshold; //max damage that can be blocked for attack type.
        force = attack->attack_force;

        // Verify target is alive.
        if(target->dead)
        {
            continue;
        }

        // Verify target is invincible,
        // or attack type is an item.
        // This is too allow item collection
        // even while invincible.
        if(target->invincible)
        {
            if(attack->attack_type != ATK_ITEM)
            {
                continue;
            }
        }

        // If attack is set to only hit
        // one entity at a _time (attackone),
        // we verify last hit (lasthit) is
        // set. If last hit is set and
        // differs from current target,
        // then we are trying to hit
        // another entity and should exit.
        if(current_anim->attackone)
        {
            if(e->lasthit)
            {
                if(target != e->lasthit)
                {
                    continue;
                }
            }
        }

        // Verify target has a match to
        // projectile hit or can damage.
        if(!(target->modeldata.type & them))
        {
            continue;
        }

        // Pain _time must have expired.
        // This is to allow reasonable delay
        // between hits so engine will not
        // run hit on every update.
        if(target->pain_time >= _time)
        {
            continue;
        }

        // Target takedamage flag
        // must be set.
        if(!target->takedamage)
        {
            continue;
        }

        // Attack IDs must be different.
        if(check_attack_id_incoming(target, current_attack_id))
        {
            continue;
        }

        // Target laying down? Exit if
        // attack only hits standing targets.
        if(target->takeaction == common_lie)
        {
            if(attack->otg == OTG_NONE)
            {
                continue;
            }
        }

        // Target NOT laying down? Exit if
        // attack only hits grounded targets.
        if(target->takeaction != common_lie)
        {
            if(attack->otg == OTG_GROUND_ONLY)
            {
                continue;
            }
        }

        // If falling, then check the juggle cost.
        if(target->falling == 1)
        {
            if(attack->jugglecost > target->modeldata.jugglepoints.current)
            {
                continue;
            }
        }

        temp = self;
        self = target;

        // Execute the doattack scripts so author can set take action
        // before the hit code below does.
        execute_ondoattack_script(self, e, attack, EXCHANGE_RECIPIANT, current_attack_id);
        execute_ondoattack_script(e, self, attack, EXCHANGE_CONFERRER, current_attack_id);

        // 2010-12-31
        // Damon V. Caskey

        // If lasthit.confirm is not true, it must have been turned off by the author; almost
        // certainly with the ondoattack event scripts above. Skip the engine's
        // default hit handling below. Useful for scripting parry systems, alternate blocking,
        // or other custom collision events.
        if(lasthit.confirm)
        {
            didhit = 1;
        }
        else
        {
            // By White Dragon
            // This line: self = temp; is the fix for
            // !lasthit.confirm bug. Without it when
            // active lasthitc 0 the damagetaker has
            // weird speedy effect.
            self = temp;
            continue;
        }

        otherowner = self; // trace top owner for opponent
        while(otherowner->owner)
        {
            otherowner = otherowner->owner;
        }

        //if #01, if they are fired by the same owner, or the owner itself
        if(topowner == otherowner)
        {
            didhit = 0;
        }

        //if #02 , ground missle checking, and bullets wont hit each other
        if( (e->owner && self->owner) ||
                (e->modeldata.ground && inair(e))  )
        {
            didhit = 0;
        }//end of if #02

        //if #05,   blocking code section
        if(didhit)
        {
            if(attack->attack_type == ATK_ITEM)
            {
                do_item_script(self, e);

                didfind_item(e);
                return;
            }
            //if #051
            if(self->toexplode == 1)
            {
                self->toexplode = 2;    // Used so the bomb type entity explodes when hit
            }
            //if #052
            if(e->toexplode == 1 && !e->modeldata.noexplode)
            {
                e->toexplode = 2;    // Used so the bomb type entity explodes when hitting
            }

            if(inair(self))
            {
                self->modeldata.jugglepoints.current = self->modeldata.jugglepoints.current - attack->jugglecost;    //reduce available juggle points.
            }

            //if #053
            if( !self->modeldata.nopassiveblock && // cant block by itself
                    validanim(self, ANI_BLOCK) && // of course, move it here to avoid some useless checking
                    ((self->modeldata.guardpoints.max == 0) || (self->modeldata.guardpoints.max > 0 && self->modeldata.guardpoints.current > 0)) &&
                    !(self->link ||
                      inair(self) ||
                      self->frozen ||
                      (self->direction == e->direction && self->modeldata.blockback < 1) ||                       // Can't block an attack that is from behind unless blockback flag is enabled
                      (!self->idling && self->attacking >= 0)) &&                                                 // Can't block if busy, attack <0 means the character is preparing to attack, he can block during this time
                    attack->no_block <= self->defense[attack->attack_type].blockpower &&       // If unblockable, will automatically hit
                    (rand32()&self->modeldata.blockodds) == 1 && // Randomly blocks depending on blockodds (1 : blockodds ratio)
                    (!self->modeldata.thold || (self->modeldata.thold > 0 && self->modeldata.thold > force)) &&
                    (!fdefense_blockthreshold ||                                                                //Specific attack type threshold.
                     (fdefense_blockthreshold > force)))
            {
                //execute the didhit script
                execute_didhit_script(e, self, attack, 1);
                self->takeaction = common_block;
                set_blocking(self);
                self->velocity.x = self->velocity.z = 0;
                ent_set_anim(self, ANI_BLOCK, 0);

                execute_didblock_script(self, e, attack);

                if(self->modeldata.guardpoints.max > 0)
                {
                    self->modeldata.guardpoints.current = self->modeldata.guardpoints.current - attack->guardcost;
                }
                ++current_anim->animhits;
                didblock = 1;    // Used for when playing the block.wav sound
                // Spawn a flash
                //if #0531
                if(!attack->no_flash)
                {
                    if(!self->modeldata.noatflash)
                    {
                        if(attack->blockflash >= 0)
                        {
                            flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, attack->blockflash, NULL);    // custom bflash
                        }
                        else
                        {
                            flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, ent_list[i]->modeldata.bflash, NULL);    // New block flash that can be smaller
                        }
                    }
                    else
                    {
                        flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, self->modeldata.bflash, NULL);
                    }
                    //ent_default_init(flash); // initiliaze this because there're no default values now

                    if(flash)
                    {
                        flash->spawntype = SPAWN_TYPE_FLASH;
                        execute_onspawn_script(flash);
                    }
                }
                //end of if #0531
            }
            else if((self->modeldata.nopassiveblock || self->modeldata.type == TYPE_PLAYER) &&  // can block by itself
                    self->blocking &&  // of course he must be blocking
                    ((self->modeldata.guardpoints.max == 0) || (self->modeldata.guardpoints.max > 0 && self->modeldata.guardpoints.current > 0)) &&
                    !((self->direction == e->direction && self->modeldata.blockback < 1) || self->frozen) &&   // Can't block if facing the wrong direction (unless blockback flag is enabled) or frozen in the block animation or opponent is a projectile
                    attack->no_block <= self->defense[attack->attack_type].blockpower &&    // Make sure you are actually blocking and that the attack is blockable
                    (!self->modeldata.thold ||
                     (self->modeldata.thold > 0 &&
                      self->modeldata.thold > force)) &&
                    (!self->defense[attack->attack_type].blockthreshold ||                   //Specific attack type threshold.
                     (self->defense[attack->attack_type].blockthreshold > force)))
            {
                // Only block if the attack is less than the players threshold
                //execute the didhit script
                execute_didhit_script(e, self, attack, 1);
                if(self->modeldata.guardpoints.max > 0)
                {
                    self->modeldata.guardpoints.current = self->modeldata.guardpoints.current - attack->guardcost;
                }
                ++current_anim->animhits;
                didblock = 1;    // Used for when playing the block.wav sound

                if(self->modeldata.blockpain && self->modeldata.blockpain <= force && self->animation == self->modeldata.animation[ANI_BLOCK]) //Blockpain 1 and in block animation?
                {
                    set_blockpain(self, attack->attack_type, 0);
                }
                execute_didblock_script(self, e, attack);

                // Spawn a flash
                if(!attack->no_flash)
                {
                    if(!self->modeldata.noatflash)
                    {
                        if(attack->blockflash >= 0)
                        {
                            flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, attack->blockflash, NULL);    // custom bflash
                        }
                        else
                        {
                            flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, ent_list[i]->modeldata.bflash, NULL);    // New block flash that can be smaller
                        }
                    }
                    else
                    {
                        flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, self->modeldata.bflash, NULL);
                    }
                    //ent_default_init(flash); // initiliaze this because there're no default values now
                    if(flash)
                    {
                        flash->spawntype = SPAWN_TYPE_FLASH;
                        execute_onspawn_script(flash);
                    }
                }
            }
            else if(self->animation->counterrange &&	// Has counter range?
                    (self->animpos >= self->animation->counterrange->frame.min && self->animpos <= self->animation->counterrange->frame.max) &&  // Current frame within counter range frames?
                    !self->frozen &&
                    (self->energy_status.health_current > force || (self->energy_status.health_current-force <= 0 && (self->animation->counterrange->condition == COUNTERACTION_CONDITION_ALWAYS_RAGE))) &&   // Rage or not?
                    // counterrange conditions
                    ( (self->animation->counterrange->condition == COUNTERACTION_CONDITION_ALWAYS) || (self->animation->counterrange->condition == COUNTERACTION_CONDITION_ALWAYS_RAGE) ||
                    (self->animation->counterrange->condition == COUNTERACTION_CONDITION_HOSTILE && e->modeldata.type & them) ||
                    (self->animation->counterrange->condition == COUNTERACTION_CONDITION_HOSTILE_FRONT_NOFREEZE && !attack->no_block && !(self->direction == e->direction) && !attack->freeze ) )

                    ) {

                    // Take damage from attack?
                    if(self->animation->counterrange->damaged == COUNTERACTION_DAMAGE_NORMAL)
                    {
                        if (self->energy_status.health_current-force <= 0)
                        {
                            // White Dragon: commented the alternative method
                            /*s_collision_attack atk;

                            atk = emptyattack;
                            atk.attack_force = force;
                            atk.attack_drop = attack->attack_drop;
                            atk.attack_type = attack->attack_type;

                            atk.dropv.y = (float)DEFAULT_ATK_DROPV_Y;
                            atk.dropv.x = (float)DEFAULT_ATK_DROPV_X;
                            atk.dropv.z = (float)DEFAULT_ATK_DROPV_Z;

                            if (e) self->takedamage(e, &atk, 0);
                            else self->takedamage(self, &atk, 0);

                            self = temp;
                            return;*/

                            self->energy_status.health_current = 1; // rage
                        }
                        else
                        {
                            self->energy_status.health_current -= force;
                        }
                    }

                    current_follow_id = animfollows[self->animation->followup.animation - 1];
                    if(validanim(self, current_follow_id))
                    {
                        if(!self->modeldata.animation[current_follow_id]->attackone)
                        {
                            self->modeldata.animation[current_follow_id]->attackone = self->animation->attackone;
                        }
                        ent_set_anim(self, current_follow_id, 0);

                        // memorize current attack ID to ignore future attacks with same ID 
                        insert_attack_id_incoming(self, current_attack_id);
                    }

                    if(!attack->no_flash)
                    {
                        if(!self->modeldata.noatflash)
                        {
                            if(attack->blockflash >= 0)
                            {
                                flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, attack->blockflash, NULL);    // custom bflash
                            }
                            else
                            {
                                flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, ent_list[i]->modeldata.bflash, NULL);    // New block flash that can be smaller
                            }
                        }
                        else
                        {
                            flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, self->modeldata.bflash, NULL);
                        }
                        //ent_default_init(flash); // initiliaze this because there're no default values now
                        if(flash)
                        {
                            flash->spawntype = SPAWN_TYPE_FLASH;
                            execute_onspawn_script(flash);
                        }
                    }
            }
            else if(self->takedamage(e, attack, 0))
            {
                // Didn't block so go ahead and take the damage
                execute_didhit_script(e, self, attack, 0);
                ++e->animation->animhits;

                e->lasthit = self;

                // Spawn a flash
                if(!attack->no_flash)
                {
                    if(self->modeldata.flashoverridesource >= 0 && self->modeldata.flashoverridesource == attack->hitflash)
                    {
                        flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, self->modeldata.flashoverridetarget, NULL);
                    }
                    else if(!self->modeldata.noatflash)
                    {
                        if(attack->hitflash >= 0)
                        {
                            flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, attack->hitflash, NULL);
                        }
                        else
                        {
                            flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, e->modeldata.flash, NULL);
                        }
                    }
                    else
                    {
                        flash = spawn(lasthit.position.x, lasthit.position.z, lasthit.position.y, 0, NULL, self->modeldata.flash, NULL);
                    }
                    if(flash)
                    {
                        flash->spawntype = SPAWN_TYPE_FLASH;
                        execute_onspawn_script(flash);
                    }
                }
                topowner->combotime = _time + combodelay; // well, add to its owner's combo

                if(e->pausetime < _time || (inair(e) && !equalairpause))        // if equalairpause is set, inair(e) is nolonger a condition for extra pausetime
                {
                    // Adds pause to the current animation
                    e->toss_time += attack->pause_add;      // So jump height pauses in midair
                    e->nextmove += attack->pause_add;      // xdir, zdir
                    e->nextanim += attack->pause_add;       //Pause animation for a bit
                    e->nextthink += attack->pause_add;      // So anything that auto moves will pause
                    e->pausetime = _time + attack->pause_add ; //UT: temporary solution
                }

                self->toss_time += attack->pause_add;       // So jump height pauses in midair
                self->nextmove += attack->pause_add;      // xdir, zdir
                self->nextanim += attack->pause_add;        //Pause animation for a bit
                self->nextthink += attack->pause_add;       // So anything that auto moves will pause

            }
            else
            {
                didhit = 0;
                continue;
            }
            // end of if #053

            // if #054
            if(flash)
            {
                if(flash->modeldata.toflip)
                {
                    flash->direction = (e->position.x > self->position.x);    // Now the flash will flip depending on which side the attacker is on
                }

                flash->base = lasthit.position.y;
                flash->autokill = 2;
            }//end of if #054

            // 2007 3 24, hmm, def should be like this
            if(didblock && !def)
            {
                def = self;
            }
            //if #055
            if((e->animation->followup.animation) && // follow up?
                    (!e->animation->counterrange) && // This isn't suppossed to be a counter, right?
                    ((e->animation->followup.condition < FOLLOW_CONDITION_HOSTILE) || (self->modeldata.type & e->modeldata.hostile)) &&                                // Does type matter?
                    ((e->animation->followup.condition < FOLLOW_CONDITION_HOSTILE_NOKILL_NOBLOCK) || ((self->energy_status.health_current > 0) && !didblock)) &&                             // check if health or not blocking matters
                    ((e->animation->followup.condition < FOLLOW_CONDITION_HOSTILE_NOKILL_NOBLOCK_NOGRAB) || ((self->energy_status.health_current > 0) && !didblock && cangrab(e, self)) ) && // check if nograb matters
                    ((e->animation->followup.condition < FOLLOW_CONDITION_HOSTILE_NOKILL_BLOCK) || ((self->energy_status.health_current > 0) && didblock))                                   // check if health or blocking matters
              )
            {
                current_follow_id = animfollows[e->animation->followup.animation - 1];
                if(validanim(e, current_follow_id))
                {
                    if(!e->modeldata.animation[current_follow_id]->attackone)
                    {
                        e->modeldata.animation[current_follow_id]->attackone = e->animation->attackone;
                    }
                    ent_set_anim(e, current_follow_id, 1);          // Then go to it!
                }
                //followed = 1; // quit loop, animation is changed
            }//end of if #055

            // memorize current attack ID to ignore future attacks with same ID 
            insert_attack_id_incoming(self, current_attack_id);
            if(self == def)
            {
                self->blocking = didblock;    // yeah, if get hit, stop blocking
            }

            //2011/11/24 UT: move the pain_time logic here,
            // because block needs this as well otherwise blockratio causes instant death
            self->pain_time = _time + (attack->pain_time ? attack->pain_time : (GAME_SPEED / 5));
            self->nextattack = 0; // reset this, make it easier to fight back
        }//end of if #05
        self = temp;

    } // end of for


    // if ###
    if(didhit)
    {
        if(current_anim->energycost)
        {
            // well, dont check player or not - UTunnels. TODO: take care of that healthcheat
            if(e == topowner && current_anim->energycost->cost > 0 && nocost && !healthcheat)
            {
                e->tocost = 1;    // Set flag so life is subtracted when animation is finished
            }
            else if(e != topowner && current_anim->energycost->cost > 0 && nocost && !healthcheat && !e->tocost) // if it is not top, then must be a shot
            {
                if(current_anim->energycost->mponly != COST_TYPE_MP_THEN_HP && topowner->energy_status.mp_current > 0)
                {
                    topowner->energy_status.mp_current -= current_anim->energycost->cost;
                    if(topowner->energy_status.mp_current < 0)
                    {
                        topowner->energy_status.mp_current = 0;
                    }
                }
                else
                {
                    topowner->energy_status.health_current -= current_anim->energycost->cost;
                    if(topowner->energy_status.health_current <= 0)
                    {
                        topowner->energy_status.health_current = 1;
                    }
                }

                e->tocost = 1;    // Little backwards, but set to 1 so cost doesn't get subtracted multiple times
            }
        }

        // New blocking checks
        //04/27/2008 Damon Caskey: Added checks for defense property specfic blockratio and type. Could probably use some cleaning.
        if(didblock && level->nohurt == DAMAGE_FROM_ENEMY_ON)
        {
            if(blockratio || def->defense[attack->attack_type].blockratio) // Is damage reduced?
            {
                if (def->defense[attack->attack_type].blockratio)                       //Typed blockratio?
                {
                    force = (int)(force * def->defense[attack->attack_type].blockratio);
                }
                else                                                                              //No typed. Use static block ratio.
                {
                    force = force / 4;
                }

                /*
                Block type handling. For backward compatibility we will use BLOCK_TYPE_MP_FIRST regardless
                of defense setting if author has enabled mpblock. Otherwise the defender's blocktype
                for incoming attack type will be used. Once this is determined, we will apply the
                appropriate blocktype accordingly.
                */
                blocktype = mpblock ? BLOCK_TYPE_MP_FIRST : def->defense[attack->attack_type].blocktype;

                switch (blocktype)
                {
                    case BLOCK_TYPE_HP:
                        //Do nothing. This is so modders can overidde energycost mponly 1 with health only.
                        break;

                    case BLOCK_TYPE_MP_ONLY:

                        def->energy_status.mp_current -= force;
                        force = 0;

                        if(def->energy_status.mp_current < 0)
                        {
                            def->energy_status.mp_current = 0;
                        }

                    case BLOCK_TYPE_MP_FIRST:

                        def->energy_status.mp_current -= force;

                        /* If there isn't enough MP to cover force, subtract remaining MP from force and set MP to 0 */
                        if(def->energy_status.mp_current < 0)
                        {
                            force = -def->energy_status.mp_current;
                            def->energy_status.mp_current = 0;
                        }
                        else
                        {
                            force = 0;
                        }

                    case BLOCK_TYPE_BOTH:

                        def->energy_status.mp_current -= force;

                        if(def->energy_status.mp_current < 0)
                        {
                            def->energy_status.mp_current = 0;
                        }
                }

                if(force < def->energy_status.health_current)                    // If an attack won't deal damage, this line won't do anything anyway.
                {
                    def->energy_status.health_current -= force;
                }
                else if(nochipdeath)                       // No chip deaths?
                {
                    def->energy_status.health_current = 1;
                }
                else
                {
                    temp = self;
                    self = def;
                    self->takedamage(e, attack, 0);           // Must be a fatal attack, then!
                    self = temp;
                }
            }
        }

        if(!didblock)
        {
            topowner->rush.time = _time + (GAME_SPEED * rush[1]);
            topowner->rush.count.current++;
            if(topowner->rush.count.current > topowner->rush.count.max && topowner->rush.count.current > 1)
            {
                topowner->rush.count.max = topowner->rush.count.current;
            }
        }

        if(didblock)
        {
            if(attack->blocksound >= 0)
            {
                sound_play_sample(attack->blocksound, 0, savedata.effectvol, savedata.effectvol, 100);    // New custom block sound effect
            }
            else if(SAMPLE_BLOCK >= 0)
            {
                sound_play_sample(SAMPLE_BLOCK, 0, savedata.effectvol, savedata.effectvol, 100);    // Default block sound effect
            }
        }
        else if(e->projectile > 0 && SAMPLE_INDIRECT >= 0)
        {
            sound_play_sample(SAMPLE_INDIRECT, 0, savedata.effectvol, savedata.effectvol, 100);
        }
        else if(attack->hitsound >= 0)
        {
            t = 100 - (noslowfx ? 0 : (force - 5));
            if(t > 100)
            {
                t = 100;
            }
            else if(t < 60)
            {
                t = 60;
            }
            sound_play_sample(attack->hitsound, 0, savedata.effectvol, savedata.effectvol, t);
        }

        if(e->remove_on_attack)
        {
            kill_entity(e);
        }
    }//end of if ###
#undef followed
}

history_functions.insert_attack_id_incoming:
void insert_attack_id_incoming(entity *e,  unsigned int attack_id_incoming)
{
    ++e->attack_id_incoming_index;
    if(e->attack_id_incoming_index >= MAX_ATTACK_IDS)
    {
        e->attack_id_incoming_index = 0;
    }
    e->attack_id_incoming[e->attack_id_incoming_index] = attack_id_incoming;
}

history_functions.check_attack_id_incoming:
int check_attack_id_incoming(entity *e,  unsigned int attack_id_incoming)
{
    int index = e->attack_id_incoming_index;

    for (int i = 0 ; i < MAX_ATTACK_IDS; ++i)
    {
        if(e->attack_id_incoming[index] == attack_id_incoming)
        {
            return 1;
        }
        else if(e->attack_id_incoming[index] == 0)
        {
            break;
        }
        --index;
        if(index < 0)
        {
            index = MAX_ATTACK_IDS - 1;
        }
    }

    return 0;
}

